    var urlParams = new URLSearchParams(window.location.search);
    var authError = urlParams.get('auth_error');
    var authMessage = urlParams.get('auth_message');
    if (authError) {
        errorDiv.textContent = authError;
        errorDiv.style.display = 'block';
    }
